    GroupCallsInput ReadGroupCalls(string id,ServerGroupRoster roster){
        if(groupDiagnosticTestInput!=null)return groupDiagnosticTestInput();
        string serverId=roster==null?"":roster.GroupId;var observations=new List<GroupMediaObservation>();if(groupVoice!=null){var v=groupVoice.DiagnosticObservation(serverId);if(v!=null)observations.Add(v);}if(groupScreen!=null)observations.AddRange(groupScreen.DiagnosticObservations(serverId));
        return new GroupCallsInput{Title=groupTelemetryTitle,Account=discovery==null?0:discovery.AccountId,Device=model.OwnId,Profile=profileSessionGeneration,Discovery=discoverySessionGeneration,Room=groupDiagnosticWindow!=null&&diagnosticContext.Section==DiagnosticSection.GroupCalls&&groupDiagnosticIdentity==id?groupDiagnosticRoom:"",VoiceStatus=groupVoice==null?null:groupVoice.Snapshot(),ScreenStatus=discovery==null||discovery.GroupRooms(serverId)==null||groupScreen==null?new GroupScreenRoomStatus[0]:discovery.GroupRooms(serverId).Rooms.Where(r=>r.Kind=="screen_share").Select(r=>groupScreen.Snapshot(serverId,r.Id)).ToArray(),Roster=roster,Authority=discovery==null||!discovery.EventChannelConnected?null:discovery.GroupRooms(serverId),Observations=observations.ToArray(),Control=discovery!=null&&discovery.EventChannelConnected?"Authenticated discovery TLS; media is separate":"No active authenticated discovery session"};
    }
    void BuildGroupTelemetrySurface(System.Windows.Controls.StackPanel actions){
        groupGraphs=new System.Windows.Controls.Button{Content="▥ Diagnostics Graph",Padding=new System.Windows.Thickness(9,6,9,6),Margin=new System.Windows.Thickness(6,0,0,0),Visibility=System.Windows.Visibility.Collapsed};groupGraphs.Click+=(s,e)=>OpenContextDiagnostics(DiagnosticSection.GroupCalls,model.SelectedGroup==null?"":model.SelectedGroup.Id);actions.Children.Insert(Math.Max(0,actions.Children.IndexOf(Find<System.Windows.Controls.Button>("GroupOverflow"))),groupGraphs);
        groupLiveRow=new System.Windows.Controls.WrapPanel{Margin=new System.Windows.Thickness(0,12,0,0),Visibility=System.Windows.Visibility.Collapsed};var header=Find<System.Windows.Controls.Border>("VoiceCard").Parent as System.Windows.Controls.StackPanel;header.Children.Insert(1,groupLiveRow);
        groupCreateVoice.Content="Voice Room";groupCreateScreen.Content="Screen Room";
        window.Closed+=(s,e)=>{if(groupDiagnosticWindow!=null)groupDiagnosticWindow.Close();groupSamples.Clear();};
    }
    void RefreshGroupTelemetry(){
        if(groupGraphs==null)return;bool selected=model.Groups&&model.SelectedGroup!=null;groupGraphs.Visibility=selected?System.Windows.Visibility.Visible:System.Windows.Visibility.Collapsed;
        if(DateTime.UtcNow<nextGroupTelemetry)return;nextGroupTelemetry=DateTime.UtcNow.AddSeconds(1);
        bool scoped=groupDiagnosticWindow!=null&&diagnosticContext.Section==DiagnosticSection.GroupCalls&&groupDiagnosticIdentity.Length>0;
        string id=scoped?groupDiagnosticIdentity:selected?model.SelectedGroup.Id:"";ServerGroupRoster roster=null;if(!scoped||groupDiagnosticProfile==profileSessionGeneration)serverGroupRosters.TryGetValue(id,out roster);
        GroupModel titledGroup;groupTelemetryTitle=model.GroupChats.TryGetValue(id,out titledGroup)?titledGroup.Name:scoped?"Selected group":"No group selected";
        groupCallDetails=GroupCallsProjection.Create(ReadGroupCalls(id,roster));groupTelemetry=groupCallDetails.Telemetry;
        string context=profileSessionGeneration+":"+discoverySessionGeneration+":"+id+":"+groupCallDetails.Context;
        string eventOwner=profileSessionGeneration+":"+discoverySessionGeneration+":"+id;if(groupEventOwner!=eventOwner){groupEventOwner=eventOwner;groupTelemetryEvents.Clear();lastGroupTelemetryState="";}if(context!=groupTelemetryContext){groupTelemetryContext=context;groupSamples.Clear();selectedGroupParticipant="";}
        string state=groupCallDetails.Lifecycle+" / "+groupTelemetry.Voice+" / "+groupTelemetry.Screen;if(state!=lastGroupTelemetryState){lastGroupTelemetryState=state;groupTelemetryEvents.Enqueue(DateTime.UtcNow.ToString("o")+" · "+ConnectionsSafeText.Clean(state));while(groupTelemetryEvents.Count>64)groupTelemetryEvents.Dequeue();}
        if(!graphsPaused){groupSamples.Enqueue(new GroupTelemetryProjection{CapturedFps=groupTelemetry.CapturedFps,EncodedFps=groupTelemetry.EncodedFps,PresentedFps=groupTelemetry.PresentedFps,UploadMbps=groupTelemetry.UploadMbps,DownloadMbps=groupTelemetry.DownloadMbps,VoiceSendMbps=groupTelemetry.VoiceSendMbps,VoiceReceiveMbps=groupTelemetry.VoiceReceiveMbps,ScreenSendMbps=groupTelemetry.ScreenSendMbps,ScreenReceiveMbps=groupTelemetry.ScreenReceiveMbps,ReceivedFps=groupTelemetry.ReceivedFps,DecodedFps=groupTelemetry.DecodedFps});while(groupSamples.Count>120)groupSamples.Dequeue();}
        var headerTelemetry=groupTelemetry;if(selected&&model.SelectedGroup.Id!=id){ServerGroupRoster headerRoster;serverGroupRosters.TryGetValue(model.SelectedGroup.Id,out headerRoster);headerTelemetry=GroupCallsProjection.Create(ReadGroupCalls(model.SelectedGroup.Id,headerRoster)).Telemetry;}
        groupLiveRow.Children.Clear();groupLiveRow.Visibility=selected&&(headerTelemetry.VoiceActive||headerTelemetry.ScreenActive)?System.Windows.Visibility.Visible:System.Windows.Visibility.Collapsed;
        foreach(var label in new[]{headerTelemetry.Voice,headerTelemetry.Screen,"Route: "+headerTelemetry.Transport,"Encoded FPS: "+GroupTelemetryProjection.Metric(headerTelemetry.EncodedFps),"↑ Payload "+GroupTelemetryProjection.Metric(headerTelemetry.UploadMbps)+" Mbps","↓ Payload "+GroupTelemetryProjection.Metric(headerTelemetry.DownloadMbps)+" Mbps"}){
            groupLiveRow.Children.Add(new System.Windows.Controls.Border{CornerRadius=new System.Windows.CornerRadius(7),Background=Brush("#142532"),BorderBrush=Brush("#2A475B"),BorderThickness=new System.Windows.Thickness(1),Margin=new System.Windows.Thickness(0,0,6,6),Padding=new System.Windows.Thickness(9),Child=new System.Windows.Controls.TextBlock{Text=label,FontSize=11,Foreground=Brush("#83CCFC")}});
        }
        UpdateGroupDiagnosticWindow();
    }
    void OpenGroupDiagnostics(){
        if(groupDiagnosticWindow!=null){groupDiagnosticWindow.Activate();return;}
        var w=new System.Windows.Window{Title=groupTelemetryTitle+" — Diagnostics & Graphs",Owner=window,Width=1080,Height=700,MinWidth=540,MinHeight=420,Resources=window.Resources,FontFamily=new System.Windows.Media.FontFamily("Segoe UI"),Background=Brush("#0D1720"),Foreground=System.Windows.Media.Brushes.LightGray,WindowStartupLocation=System.Windows.WindowStartupLocation.CenterOwner};groupDiagnosticWindow=w;
        var root=new System.Windows.Controls.DockPanel{Margin=new System.Windows.Thickness(14)};BuildDiagnosticNavigation(root);var controls=new System.Windows.Controls.WrapPanel{Margin=new System.Windows.Thickness(0,8,0,0)};System.Windows.Controls.DockPanel.SetDock(controls,System.Windows.Controls.Dock.Bottom);root.Children.Add(controls);
        Action<string,Action> action=(label,callback)=>{var b=new System.Windows.Controls.Button{Content=label,Tag=label,Background=Brush("#172A38"),Foreground=Brush("#EDF1F5"),BorderBrush=Brush("#2B4355"),Padding=new System.Windows.Thickness(12,7,12,7),Margin=new System.Windows.Thickness(0,0,8,0)};b.Click+=(s,e)=>callback();controls.Children.Add(b);};
        action("Copy Diagnostics",()=>CopyDiagnosticText(CurrentDiagnosticExport(),diagnosticContext.Section==DiagnosticSection.Connections&&connectionsDeveloperPreview?"Sample connections preview copied (not a real report).":"Diagnostics copied."));action("Export…",()=>{var pick=new Microsoft.Win32.SaveFileDialog{FileName=diagnosticContext.Section==DiagnosticSection.Connections&&connectionsDeveloperPreview?"PeerChat-SAMPLE-connections.txt":"PeerChat-diagnostics.txt",Filter="Text|*.txt"};if(pick.ShowDialog(w)==true)try{System.IO.File.WriteAllText(pick.FileName,CurrentDiagnosticExport(),new System.Text.UTF8Encoding(false));}catch{Notify("Could not export diagnostics.");}});
        action("Pause graphs",()=>{if(diagnosticContext.Section==DiagnosticSection.DirectMessageCalls&&!dmDeveloperPreview){dmGraphsPaused=!dmGraphsPaused;dmHistory.Paused=dmGraphsPaused;RefreshDiagnosticFooter();return;}if(diagnosticContext.Section==DiagnosticSection.FileTransfers){transferDiagnosticHistory.Paused=!transferDiagnosticHistory.Paused;RefreshDiagnosticFooter();return;}graphsPaused=!graphsPaused;((System.Windows.Controls.Button)controls.Children[2]).Content=graphsPaused?"Resume graphs":"Pause graphs";RefreshDiagnosticLayout();});action("Close",()=>w.Close());
        groupDiagnosticTabs=new System.Windows.Controls.TabControl{Background=Brush("#0D1720"),BorderThickness=new System.Windows.Thickness(0),ItemContainerStyle=diagnosticSecondaryTabs,Template=DiagnosticTabContainer(false),ItemsPanel=DiagnosticTabPanel()};foreach(string tab in new[]{"Overview","Screen Share","Voice","Participants","Network","Events","Export"})groupDiagnosticTabs.Items.Add(new System.Windows.Controls.TabItem{Header=tab});root.Children.Add(groupDiagnosticTabs);w.Content=root;BindConnectionsViewRefresh(w);BindTransferViewRefresh(w);BindDmViewRefresh(w);BindHistoryDiagnosticRefresh(w);BindLogsDiagnosticRefresh(w);w.Closed+=(s,e)=>{groupDiagnosticWindow=null;groupDiagnosticTabs=null;graphsPaused=false;diagnosticNavigation=null;diagnosticExamples=null;connectionPreviewExamples=null;connectionPreviewStatePanel=null;connectionPreview=null;diagnosticBanner=null;};diagnosticNavigation.SelectedIndex=(int)diagnosticContext.Section;RefreshDiagnosticLayout();w.Show();
    }
    string GroupDiagnosticExport(){return ConnectionsSafeText.Clean("PeerChat group telemetry/v2\nBuild: "+PeerChat.VersionInfo.Display+"\nCaptured UTC: "+DateTime.UtcNow.ToString("o")+"\n"+groupTelemetry.Text+"\n"+groupCallDetails.Overview+"\n"+groupCallDetails.Voice+"\n"+groupCallDetails.Screen+"\n"+groupCallDetails.Network+"\nHistory Sync: "+(archiveProgress==null?"Not available":archiveProgress.CurrentActivity+"\n"+archiveProgress.LastResultSummary)+"\nEvents:\n"+String.Join("\n",groupTelemetryEvents));}
