        SetGroupPage(5,GroupDiagnosticText(String.Join("\n",groupTelemetryEvents)));
        SetGroupPage(6,GroupDiagnosticText(GroupDiagnosticExport()));
    }
    void SetGroupPage(int index,System.Windows.FrameworkElement page){var tab=(System.Windows.Controls.TabItem)groupDiagnosticTabs.Items[index];var previous=tab.Content as System.Windows.Controls.ScrollViewer;double offset=previous==null?0:previous.VerticalOffset;tab.Content=page;var next=page as System.Windows.Controls.ScrollViewer;if(next!=null&&offset>0)next.Loaded+=(s,e)=>next.ScrollToVerticalOffset(offset);}
